<script setup lang="ts">
import { computed, onScopeDispose, shallowRef, watch } from 'vue'
import { ElButton } from 'element-plus'
import ValidationSummary from './ValidationSummary.vue'
import ReleaseHistory from './ReleaseHistory.vue'
import SubscriptionLink from './SubscriptionLink.vue'
import ImportIssuesPanel from '../import/ImportIssuesPanel.vue'
import { ApiError, errorMessage, request } from '../../api/client'
import { downloadText } from '../rules/ruleText'
import type { ProfileDocument, PublishPreview, ReleaseView, ValidationReport } from '../../types/domain'
const props=defineProps<{profileId:string;draft:ProfileDocument;version:string;dirty:boolean;publishedVersion:string|null}>()
const emit=defineEmits<{published:[release:ReleaseView,submitted:ProfileDocument];conflict:[];resolveImportIssues:[]}>()
const preview=shallowRef<PublishPreview|null>(null),report=shallowRef<ValidationReport|null>(null),releases=shallowRef<ReleaseView[]>([]),busy=shallowRef(false),historyBusy=shallowRef(false),error=shallowRef(''),historyError=shallowRef(''),acknowledged=shallowRef(false),showYaml=shallowRef(false)
const current=computed(()=>releases.value[0]??null),currentVersion=computed(()=>current.value?.version??props.publishedVersion)
const hasWarnings=computed(()=>Boolean(preview.value?.emptyGroupIds.length||report.value?.warnings.length))
const canPublish=computed(()=>Boolean(preview.value&&!report.value?.errors.length&&!props.draft.importIssues.length&&(!hasWarnings.value||acknowledged.value)&&!busy.value))
let sequence=0,historySequence=0,disposed=false,validation:AbortController|null=null,historyRead:AbortController|null=null;const lifetime=new AbortController()
watch([()=>props.profileId,()=>props.draft,()=>props.version],()=>{sequence++;validation?.abort();preview.value=null;report.value=null;acknowledged.value=false;showYaml.value=false}, {flush:'sync'})
watch([()=>props.profileId,()=>props.publishedVersion],(value,old)=>{if(value[0]!==old?.[0])releases.value=[];void loadHistory()},{immediate:true})
onScopeDispose(()=>{disposed=true;sequence++;historySequence++;validation?.abort();historyRead?.abort();lifetime.abort();preview.value=null})
async function loadHistory(){const currentRead=++historySequence;historyRead?.abort();historyRead=new AbortController();historyBusy.value=true;historyError.value='';try{const values=await request<ReleaseView[]>(`/profiles/${props.profileId}/releases`,{signal:historyRead.signal});if(currentRead===historySequence&&!disposed)releases.value=values}catch(cause){if(currentRead===historySequence&&!disposed)historyError.value=errorMessage(cause)}finally{if(currentRead===historySequence)historyBusy.value=false}}
function failed(cause:unknown){error.value=errorMessage(cause);if(cause instanceof ApiError){if(cause.status===409)emit('conflict');if(cause.status===422&&cause.data&&typeof cause.data==='object'&&'errors' in cause.data)report.value=cause.data as ValidationReport}}
async function validate(){if(busy.value)return;const currentRead=++sequence;validation?.abort();validation=new AbortController();busy.value=true;error.value='';report.value=null;preview.value=null;acknowledged.value=false;showYaml.value=false;try{const result=await request<PublishPreview>(`/profiles/${props.profileId}/validate`,{method:'POST',body:{expectedVersion:props.version,document:props.draft},signal:validation.signal});if(currentRead===sequence&&!disposed){preview.value=result;report.value=result.report}}catch(cause){if(currentRead===sequence&&!disposed)failed(cause)}finally{busy.value=false}}
async function publish(){if(!canPublish.value)return;const submitted=JSON.parse(JSON.stringify(props.draft))as ProfileDocument,id=props.profileId,version=props.version;busy.value=true;error.value='';try{const release=await request<ReleaseView>(`/profiles/${id}/publish`,{method:'POST',body:{expectedVersion:version,document:submitted},signal:lifetime.signal});if(disposed||id!==props.profileId)return;releases.value=[release,...releases.value.filter(value=>value.id!==release.id)];emit('published',release,submitted)}catch(cause){if(!disposed)failed(cause)}finally{busy.value=false}}
</script>
<template><div class="publish-stack"><ImportIssuesPanel :key="profileId" :profile-id="profileId" :issues="draft.importIssues" @resolved="emit('resolveImportIssues')" /><section class="panel"><header class="panel-header"><div><h2>{{currentVersion?`当前发布 v${currentVersion}`:'尚未发布'}}</h2><p class="muted">{{dirty?'当前工作副本包含未保存编辑，发布时一并保存。':'发布当前已保存的方案定义。'}}</p></div><span class="tag">草稿 v{{version}}</span></header><div class="panel-body"><p class="muted">先校验当前工作副本，确认摘要后发布。上游自动刷新使用已发布定义。</p><ValidationSummary :preview="preview" :report="report" :groups="draft.groups" :previous-node-count="current?.nodeCount??null" :previous-digest="current?.yamlDigest??null" /><p v-if="error" class="error publish-error" role="alert">{{error}}</p><label v-if="preview&&hasWarnings&&!report?.errors.length" class="warning-accept"><input v-model="acknowledged" type="checkbox" aria-label="确认发布警告">已阅读警告，确认按此配置发布</label><div class="publish-controls"><ElButton :loading="busy" @click="validate">校验并预览</ElButton><ElButton v-if="preview?.yaml" :disabled="busy" @click="showYaml=!showYaml">{{showYaml?'隐藏 YAML':'显示 YAML 预览'}}</ElButton><ElButton type="primary" :disabled="!canPublish" :loading="busy" @click="publish">发布当前工作副本</ElButton></div><div v-if="showYaml&&preview?.yaml" class="yaml-preview"><p class="warning">预览包含节点连接凭据，请妥善保管下载文件。</p><pre>{{preview.yaml}}</pre><ElButton @click="downloadText('clash-profile.yaml',preview!.yaml!,'application/yaml')">下载 YAML 预览</ElButton></div></div></section><SubscriptionLink :key="profileId" :profile-id="profileId" :published="Boolean(currentVersion)" /><p v-if="historyError" class="error" role="alert">{{historyError}}</p><ReleaseHistory :releases="releases" :busy="historyBusy" @reload="loadHistory" /></div></template>
<style scoped>.publish-stack{display:grid;gap:20px}.publish-controls{display:flex;gap:9px;flex-wrap:wrap;margin-top:22px}.warning-accept{margin-top:18px;color:var(--warn)}.publish-error{margin-top:16px}.yaml-preview{margin-top:24px}.yaml-preview pre{background:var(--canvas);padding:18px;max-height:450px;overflow:auto;white-space:pre}.publish-stack>.import-issues{margin-bottom:0}</style>
